// Index of current language in the [de, fr, zh] arrays; null while in English.
function KA_idx() {
  var i = { de: 0, fr: 1, zh: 2 };
  return (typeof LANG !== 'undefined') ? i[LANG] : undefined;
}

// Localized verb meaning, e.g. "to speak" -> "sprechen". Falls back to English.
window.KA_meaning = function (en) {
  var i = KA_idx();
  if (i === undefined || !en) return en;
  var m = KA_VERB_MEANINGS[en];
  return (m && m[i]) ? m[i] : en;
};

// Localized phrase prompt, e.g. volitional + "to speak" -> „lass uns sprechen“ →
// Returns null when English should be used (app.js keeps its own template).
window.KA_phrase = function (formKey, enMeaning) {
  var i = KA_idx();
  if (i === undefined) return null;
  var tpl = KA_PHRASES[formKey];
  if (!tpl || !tpl[i]) return null;
  return tpl[i].replace('{m}', window.KA_meaning(enMeaning));
};

// Language name for AI prompts sent to the backend, so hints and feedback
// come back in the language the learner selected.
window.KA_aiLang = function () {
  var names = { de: 'German', fr: 'French', zh: 'Simplified Chinese' };
  return (typeof LANG !== 'undefined' && names[LANG]) ? names[LANG] : null;
};
window.KA_aiLangSuffix = function () {
  var n = window.KA_aiLang();
  return n ? ('\n\nIMPORTANT: Write your entire response in ' + n +
    '. Keep all Japanese text (kana, kanji) in Japanese.') : '';
};
